#include <stdio.h>

int main() {
    const char *expr = "23*54*+9-";
    int stack[20];
    int top = -1;
    for (int i = 0; expr[i] != '\0'; i++) {
        char c = expr[i];
        if (c >= '0' && c <= '9') {
            stack[++top] = c - '0';
        } else {
            int b = stack[top--];
            int a = stack[top--];
            if (c == '+') stack[++top] = a + b;
            else if (c == '-') stack[++top] = a - b;
            else if (c == '*') stack[++top] = a * b;
            else if (c == '/') stack[++top] = a / b;
        }
    }
    printf("Result: %d\n", stack[top]);
    return 0;
}
